description:
This PR adds several functions to get the tags on the RStudio Connect system. 

- `get_tags` - this just returns the simple two column data.frame returned from the `get_tags` R6 method. 
- `get_tag_info` - this parses the information from the `get_tag_tree` R6 method into a tibble
- `get_tag_tree` - this steals the concept from `fs::dir_tree` and creates a tree in the console of the tags. I have posted a reprex showing what it looks like below. Note that the `get_tag_tree` function only needs the valid connect source object and will create the tree from the servers tags. The reprex just creates the tags via a helper function and runs it through the internal function within `get_tag_tree`. 

Some things to note about the PR which might be issues:
- It adds `stringr` to the Imports section of description. I needed `str_extract`, so I added it. If this is a dealbreaker (i.e. you want to limit your dependencies) then I can rework it with base R
- the `get_tag_info` doesn't utilize the `src$tags`  list but rather the nested list from `src$get_tag_tree`. The helper function seems to work fine but I am not sure whether it would be better to just initiate the creation of `src$tags` and make the parse function a little more robust. I am open to suggestions and will make changes accordingly. 


## Reprex for `get_tag_tree` functionality
``` r
# function to make example tags
make_tags <- function(n, child = NULL){
  purrr::map(1:n, ~{
    name <- randomNames::randomNames(n = 1, which.names = "first")
    out <- list(
      name = name,
      children = NULL
    )
    
    if (!is.null(child)){
      out$children <- make_tags(n = child)
    }
    
    return(out)
  })
}

tmp <- make_tags(2, 2)

tmp[[2]]$children[[2]]$children <- make_tags(3, child = 1)
tmp[[1]]$children[[1]]$children <- make_tags(2, 1)


# functions to make tag_tree
tag_tree <- function(tags, top_tag = "tags"){
  parsed_tags <- parse_tags(tags, top_tag = top_tag)
  
  tag_split <- split(parsed_tags, tag_ancestor(parsed_tags))
  names(tag_split) <- gsub("/$", "", names(tag_split))
  
  ch <- fs:::box_chars()
  
  print_leaf <- function(x, indent) {
    leafs <- tag_split[[x]]
    for (i in seq_along(leafs)) {
      if (i == length(leafs)) {
        cat(indent, fs:::pc(ch$l, ch$h, ch$h, " "), basename(leafs[[i]]), "\n", sep = "")
        print_leaf(leafs[[i]], paste0(indent, "    "))
      } else {
        cat(indent, fs:::pc(ch$j, ch$h, ch$h, " "), basename(leafs[[i]]), "\n", sep = "")
        print_leaf(leafs[[i]], paste0(indent, fs:::pc(ch$v, "   ")))
      }
    }
  }
  
  cat(top_tag(parsed_tags), "\n", sep = "")
  print_leaf(top_tag(parsed_tags), indent = "")
}


parseTags <- function(x){
  parsed_tags <- purrr::map(x, ~{
    out <- .x$name
    # out <- paste(top_tag, out, sep = "/")
    if (length(.x$children) > 0){
      child_names <- parseTags(.x$children)
      child_names <- paste(out, child_names, sep = "/")
      out <- c(out, child_names)
    } 
    
    return(out)
  })
  
  parsed_tags <- purrr::flatten_chr(parsed_tags)
  out <- gsub("/$", "", parsed_tags)
  
  return(out)
}

parse_tags <- function(x, top_tag = "tags"){
  out <- parseTags(x)
  
  out <- paste(top_tag, out, sep = "/")
  return(out)
}

tag_ancestor <- function(x){
  out <- stringr::str_extract(x, "^(.*[\\/])")
  out <- ifelse(is.na(out), paste0(x, "/"), out)
  return(out)
}

top_tag <- function(x){
  unique(stringr::str_extract(x, "^[^/]+"))
}

# print the tag tree
tag_tree(tmp)
#> tags
#> +-- Morgan
#> |   +-- Cherise
#> |   |   +-- Alma
#> |   |   |   \-- Dong-Keun
#> |   |   \-- Rebekah
#> |   |       \-- Omar
#> |   \-- Jessica
#> \-- Michaela
#>     +-- John
#>     \-- Anabella
#>         +-- Jacob
#>         |   \-- Briana
#>         +-- Tyler
#>         |   \-- Damien
#>         \-- Taylor
#>             \-- Antonio
```

